int replace_map_pointers(struct verifier_env *env) {
    const struct bpf_insn *insn;
    struct bpf_map *map;
    int i, err;

    for (i = 0; i < env->prog->len; i++) {
        insn = &env->prog->insnsi[i];
        if (insn->code != (BPF_LDX | BPF_IMM | BPF_DW) &&
            insn->code != (BPF_STX | BPF_MEM | BPF_DW))
            continue;

        if (insn->code == (BPF_LDX | BPF_IMM | BPF_DW)) {
            if (insn->src_reg != BPF_PSEUDO_MAP_FD)
                continue;

            map = bpf_get_map_with_id(insn->off);
            if (!map)
                return -ENOENT;

            if (env->used_maps >= MAX_USED_MAPS) {
                bpf_map_put(map);
                return -ENOMEM;
            }

            env->used_maps++;
            insn->src_reg = 0;
            insn->off = 0;
            insn->imm = (u32)(unsigned long)map;
            insn = &env->prog->insnsi[i + 1];
            insn->code = 0;
            insn->dst_reg = 0;
            insn->src_reg = 0;
            insn->off = 0;
            insn->imm = (((u64)(unsigned long)map) >> 32) & 0xFFFFFFFF;
            env->prog->aux->used_maps[env->used_maps - 1] = map;
        }
    }

    return 0;
}

int replace_map_pointers(struct verifier_env *env) {
    int i;
    struct bpf_insn *insn;
    struct bpf_map *map = NULL;
    int fd, err = 0;

    for (i = 0; i < env->prog->len; i++) {
        insn = &env->prog->insnsi[i];

        if (BPF_CLASS(insn->code) == BPF_LDX ||
            BPF_CLASS(insn->code) == BPF_STX) {
            if (insn->src_reg != BPF_PSEUDO_MAP_FD)
                continue;
            fd = insn->imm;
            map = bpf_map_get(fd);
            if (!map) {
                return -ENOENT;
            }

            if (env->used_maps_count >= MAX_USED_MAPS) {
                bpf_map_put(map);
                return -E2BIG;
            }

            insn->imm = (uintptr_t)map;
            insn->src_reg = 0; /* Clear pseudo FD */
            env->used_maps[env->used_maps_count++] = map;
        }

        if ((BPF_CLASS(insn->code) == BPF_LD &&
             BPF_MODE(insn->code) == BPF_IMM &&
             BPF_SIZE(insn->code) == BPF_DW)) {
            if (insn->src_reg != BPF_PSEUDO_MAP_FD)
                continue;
            fd = insn->imm;
            map = bpf_map_get(fd);
            if (!map) {
                return -ENOENT;
            }

            if (env->used_maps_count >= MAX_USED_MAPS) {
                bpf_map_put(map);
                return -E2BIG;
            }

            insn->imm = (uintptr_t)map;
            env->used_maps[env->used_maps_count++] = map;
        }
    }

    for (i = 0; i < env->used_maps_count; i++)
        bpf_map_inc(env->used_maps[i]);

    return 0;
}

int replace_map_fds_with_pointers(struct verifier_env *env) {
    struct bpf_insn *insn;
    int i, err;
    struct bpf_map *map;

    for (i = 0; i < env->prog->len; i++) {
        insn = &env->prog->insnsi[i];

        if (BPF_CLASS(insn->code) != BPF_LD && BPF_CLASS(insn->code) != BPF_LDX &&
            BPF_CLASS(insn->code) != BPF_ST && BPF_CLASS(insn->code) != BPF_STX)
            continue;

        if (BPF_MODE(insn->code) != BPF_IMM || BPF_SIZE(insn->code) != BPF_DW)
            continue;

        if (insn->src_reg != BPF_PSEUDO_MAP_FD)
            continue;

        if (env->used_maps >= MAX_USED_MAPS)
            return -ENOMEM;

        map = bpf_get_map_with_fd(insn->imm);
        if (!map)
            return -ENOENT;

        insn->src_reg = 0;
        insn->imm = 0;
        insn->off = 0;
        insn->code = BPF_LDX | BPF_MEM | BPF_DW;
        env->maps[env->used_maps++] = map;
        err = bpf_map_inc_ref(map);
        if (err) {
            bpf_map_put(map);
            return err;
        }
    }

    return 0;
}

int replace_map_fds_with_pointers(struct verifier_env *env) {
    int i;
    struct bpf_insn *insn;
    int err = 0;

    for (i = 0; i < env->prog->len; i++) {
        insn = &env->prog->insnsi[i];

        if (insn->code != (BPF_LDX | BPF_IMM | BPF_DW) && insn->code != (BPF_STX | BPF_IMM | BPF_DW))
            continue;

        if (insn->src_reg != BPF_PSEUDO_MAP_FD)
            continue;

        struct bpf_map *map = bpf_get_map_with_fd(insn->imm);
        if (!map)
            return -EINVAL;

        if (env->used_maps_count >= MAX_USED_MAPS)
            return -ENOMEM;

        insn->imm = (unsigned long)map;
        env->used_maps[env->used_maps_count++] = map;
        bpf_map_ref_inc(map);
    }

    return 0;
}

int replace_map_fds_with_pointers(struct verifier_env *env) {
    struct bpf_insn *insn;
    int i, err;
    struct bpf_map *map;

    for (i = 0; i < env->prog->len; i++) {
        insn = &env->prog->insnsi[i];

        if (insn->code == (BPF_LDX | BPF_IMM | BPF_DW)) {
            if (!is_pseudo_map_fd(insn->src_reg)) {
                return -EINVAL;
            }

            map = get_bpf_map_from_fd(insn->src_reg);
            if (!map) {
                return -ENOENT;
            }

            if (env->used_maps >= MAX_USED_MAPS) {
                bpf_map_put(map);
                return -ENOMEM;
            }

            insn->src_reg = PTR_TO_MAP;
            insn->off = (u32)(unsigned long)map;
            env->used_maps++;
            env->maps[env->used_maps - 1] = map;
            bpf_map_get(map);
        } else if (insn->code == (BPF_STX | BPF_IMM | BPF_DW)) {
            if (insn->src_reg != PTR_TO_MAP) {
                return -EINVAL;
            }

            map = (struct bpf_map *)(unsigned long)insn->off;
            if (!map) {
                return -EINVAL;
            }

            if (env->used_maps >= MAX_USED_MAPS) {
                return -ENOMEM;
            }

            env->used_maps++;
            env->maps[env->used_maps - 1] = map;
            bpf_map_get(map);
        } else {
            continue;
        }
    }

    return 0;
}
